#include "document.h"
#include "document_snapshot.h"
#include "project_encode.h"
#include "project_import.h"
#include <iostream>
using namespace moon;using namespace moon::project;
void check(bool v,const char* text){if(!v)throw std::runtime_error(text);}
Document opened(std::shared_ptr<const Bytes> bytes){auto a=prepareEditableImport(readProjectManifest(bytes));PaletteState p;p.entries.clear();p.slots=a.palette.slots;p.nextId=a.palette.nextId;p.columns=a.palette.columns;for(const auto& e:a.palette.entries)p.entries.push_back({e.id,e.name,e.color});return Document::fromImported(a.width,a.height,std::move(a.timeline),std::move(p),a.id,a.name,a.sourceArchive);}
int main(){try{Document base(2,1);const auto original=encodeEditableProject(base).bytes;check(base.palette().columns==8&&readProjectManifest(original).paletteColumns==8,"New document stored columns default");
 for(int columns:{1,4,256}){auto palette=base.palette();palette.columns=columns;palette.slots.assign(columns==1?4:columns,0);palette.slots[0]=1;palette.slots[2]=2;auto d=Document::fromImported(2,1,base.timeline().state(),palette,readProjectManifest(original).id,U"columns",original);const auto slots=d.palette().slots;d.beginStroke({0,0},0xff123456);d.commitStroke();auto saved=encodeEditableProject(d);auto manifest=readProjectManifest(saved.bytes);check(manifest.paletteColumns==columns&&manifest.paletteSlots==slots,"Save retained stale source columns");auto fresh=opened(saved.bytes);check(fresh.palette().columns==columns&&fresh.palette().slots==slots&&fresh.pixels()[0]==0xff123456,"Fresh reopen columns/holes/pixels");DocumentSnapshot snapshot(fresh);while(!snapshot.advance(fresh,std::chrono::steady_clock::now()+std::chrono::seconds(1))){}auto copy=snapshot.finish();check(copy.palette().columns==columns&&copy.palette().slots==slots,"Snapshot columns");auto recovered=opened(encodeRecoveryProject(copy).bytes);check(recovered.palette().columns==columns&&recovered.palette().slots==slots,"Recovery columns");auto again=opened(encodeEditableProject(recovered).bytes);check(again.palette().columns==columns&&again.palette().slots==slots,"Recovery normal-save columns");}
 for(int columns:{0,257}){auto palette=base.palette();palette.columns=columns;bool refused=false;try{Document::fromImported(2,1,base.timeline().state(),palette,"bad",U"bad",original);}catch(const std::invalid_argument&){refused=true;}check(refused,"Invalid stored columns imported");}
 std::cout<<"Stored palette columns default/bounds/source overwrite/holes/save/reopen/snapshot/recovery passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
